const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const spaw = @import("spawn"); const regi = @import("registry"); const supe = @import("tasksuper"); const prob = @import("taskprobe"); const conf = @import("store"); const stre = @import("stream");
const tktickbase = @import("tk-tick-base.zig"); const ArmeReje = tktickbase.ArmeReje; const CF = tktickbase.CF; const CatcReqz = tktickbase.CatcReqz; const ChaiFini = tktickbase.ChaiFini; const ChaiRunz = tktickbase.ChaiRunz; const ChaiView = tktickbase.ChaiView; const Jobz = tktickbase.Jobz; const PollReqz = tktickbase.PollReqz; const RunzLast = tktickbase.RunzLast; const RunzLastReco = tktickbase.RunzLastReco; const RunzResu = tktickbase.RunzResu; const RunzSlot = tktickbase.RunzSlot; const StarReqz = tktickbase.StarReqz; const chaiResu = tktickbase.chaiResu; const finiPush = tktickbase.finiPush; const intoDupe = tktickbase.intoDupe; const jobzClon = tktickbase.jobzClon; const jobzFill = tktickbase.jobzFill; const logzDirz = tktickbase.logzDirz; const logzRota = tktickbase.logzRota; const membNext = tktickbase.membNext; const nowzMsec = tktickbase.nowzMsec; const plusPick = tktickbase.plusPick; const poolCoun = tktickbase.poolCoun; const poolPick = tktickbase.poolPick; const recoLast = tktickbase.recoLast; const ringDrop = tktickbase.ringDrop; const ringNote = tktickbase.ringNote; const ringSeal = tktickbase.ringSeal; const taskFind = tktickbase.taskFind;
const Sche = @import("tk-task-tick.zig").Sche;
pub fn loopReco(self: *Sche, iozz: std.Io) void { var stop_list: [16][]const u8 = undefined; var stop_coun: usize = 0; var star_list: [16]StarReqz = undefined; var star_coun: usize = 0; { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const list = if (self.load) |load| load.task else &[_]stor.Task{}; var iter = self.loop.iterator(); while (iter.next()) |entr| { const iden = entr.key_ptr.*; const supz = entr.value_ptr.*; const keep = blk: { const task = taskFind(list, iden) orelse break :blk false; if (!task.on) break :blk false; if (!std.mem.eql(u8, task.type, "loop")) break :blk false; if (!std.mem.eql(u8, task.run, supz.cmdz)) break :blk false; break :blk true; }; if (!keep and stop_coun < stop_list.len) { stop_list[stop_coun] = iden; stop_coun += 1; } } for (self.arme) |*arme| { if (!arme.isLoop()) continue; if (self.loop.contains(arme.id)) continue; const task = taskFind(list, arme.id) orelse continue; if (star_coun >= star_list.len) break; const reqz = &star_list[star_coun]; reqz.* = .{}; reqz.iden = intoDupe(&reqz.iden_buff, arme.id); reqz.runz = intoDupe(&reqz.runz_buff, task.run); reqz.cwdz = intoDupe(&reqz.cwdz_buff, task.cwd orelse self.root); reqz.shel = intoDupe(&reqz.shel_buff, task.shell orelse ""); star_coun += 1; } } for (stop_list[0..stop_coun]) |iden| self.loopStop(iozz, iden); for (star_list[0..star_coun]) |*reqz| self.loopStar(iozz, reqz); }
pub fn loopStar(self: *Sche, iozz: std.Io, reqz: *const StarReqz) void { const supz = supe.Supe.crea(self.gpaz, reqz.iden, reqz.runz, reqz.cwdz, spaw.shelPars(reqz.shel)) catch return; const thre = std.Thread.spawn(.{}, loopThre, .{ self, iozz, supz }) catch { supz.dest(); return; }; thre.detach(); self.mute.lock(iozz) catch { supz.stopSign(iozz, &self.regz); return; }; defer self.mute.unlock(iozz); const keyz = self.gpaz.dupe(u8, reqz.iden) catch { supz.stopSign(iozz, &self.regz); return; }; self.loop.put(self.gpaz, keyz, supz) catch { self.gpaz.free(keyz); supz.stopSign(iozz, &self.regz); }; }
pub fn loopStop(self: *Sche, iozz: std.Io, iden: []const u8) void { var supz: ?*supe.Supe = null; var keyz: ?[]const u8 = null; self.mute.lock(iozz) catch return; if (self.loop.fetchRemove(iden)) |pair| { keyz = pair.key; supz = pair.value; } self.mute.unlock(iozz); if (supz) |vict| { vict.stopSign(iozz, &self.regz); _ = vict.exitWait(iozz, 3000); vict.dest(); } if (keyz) |keyd| self.gpaz.free(keyd); }
pub fn loopEmerStop(self: *Sche) void { var iter = self.loop.iterator(); while (iter.next()) |entr| entr.value_ptr.*.stop.store(true, .release); self.regz.allzUnloKill(); }
pub fn loopAllzStop(self: *Sche, iozz: std.Io) void { var iter = self.loop.iterator(); while (iter.next()) |entr| { const supz = entr.value_ptr.*; supz.stopSign(iozz, &self.regz); _ = supz.exitWait(iozz, 2000); supz.dest(); self.gpaz.free(entr.key_ptr.*); } self.loop.clearRetainingCapacity(); self.loop.deinit(self.gpaz); self.loop = .empty; }
pub fn loopThre(self: *Sche, iozz: std.Io, supz: *supe.Supe) void { defer supz.exit.store(true, .release); while (!supz.stop.load(.acquire)) { const star_msec = nowzMsec(iozz); var aren = std.heap.ArenaAllocator.init(self.gpaz); const allo = aren.allocator(); var sink: std.Io.Writer.Discarding = .init(&.{}); const code = spaw.runz(allo, iozz, &sink.writer, &self.regz, .{ .cmdz = supz.cmdz, .cwdz = supz.cwdz, .shel = supz.shel, .jobz_iden = supz.iden, .envi = null }, star_msec) catch -1; aren.deinit(); const runz_msec = nowzMsec(iozz) - star_msec; _ = self.fire_coun.fetchAdd(1, .monotonic); _ = supz.rest.fetchAdd(1, .monotonic); if (self.mute.lock(iozz)) |_| { for (self.arme) |*arme| { if (std.mem.eql(u8, arme.id, supz.iden)) { arme.markFired(nowzMsec(iozz)); break; } } self.mute.unlock(iozz); } else |_| {} var jobz: Jobz = .{}; jobz.iden = intoDupe(&jobz.iden_buff, supz.iden); jobz.runz = intoDupe(&jobz.runz_buff, supz.cmdz); self.fireLogz(iozz, &jobz, .{ .code = code, .elap_msec = runz_msec }) catch {}; if (supz.stop.load(.acquire)) break; if (supe.runzHeal(runz_msec)) { supz.back_msec = supe.CF.back_minz_msec; } else { supz.back_msec = supe.backNext(supz.back_msec); } var slep: u32 = 0; while (slep < supz.back_msec and !supz.stop.load(.acquire)) { const step = @min(@as(u32, 100), supz.back_msec - slep); std.Io.sleep(iozz, .fromMilliseconds(step), .awake) catch break; slep += step; } } }
pub fn probThre(self: *Sche, iozz: std.Io) void { defer self.prob_exit.store(true, .release); while (!self.stop.load(.acquire)) { self.probPoll(iozz); std.Io.sleep(iozz, .fromMilliseconds(CF.tick_msec), .awake) catch break; } }
pub fn probPoll(self: *Sche, iozz: std.Io) void { var pool: [32]PollReqz = undefined; var coun: usize = 0; const nowz_msec = nowzMsec(iozz); { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); for (self.arme) |*arme| { if (coun >= pool.len) break; const pntr = arme.probePtr() orelse continue; if (!pntr.pollDuez(nowz_msec)) continue; const reqz = &pool[coun]; reqz.* = .{}; reqz.iden = intoDupe(&reqz.iden_buff, arme.id); reqz.prob = pntr.*; coun += 1; } } if (coun == 0) return; var hits: [32]bool = @splat(false); for (pool[0..coun], 0..) |*reqz, indx| hits[indx] = reqz.prob.poll(iozz, nowz_msec); var duez_buff: [32]Jobz = undefined; var duez_coun: usize = 0; { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const list = if (self.load) |load| load.task else &[_]stor.Task{}; for (pool[0..coun], 0..) |*reqz, indx| { for (self.arme) |*arme| { if (!std.mem.eql(u8, arme.id, reqz.iden)) continue; const live = arme.probePtr() orelse break; if (live.kind != reqz.prob.kind) break; live.adop(&reqz.prob); if (!hits[indx]) break; const task = taskFind(list, arme.id) orelse break; if (duez_coun >= duez_buff.len) break; jobzFill(&duez_buff[duez_coun], arme.id, task); arme.markFired(nowz_msec); duez_coun += 1; break; } } } if (duez_coun > 0) { _ = self.fire_coun.fetchAdd(@intCast(duez_coun), .monotonic); self.disp(iozz, duez_buff[0..duez_coun]); } }
pub fn loopStat(self: *Sche, iden: []const u8) ?struct { rest: u32, aliv: bool } { const supz = self.loop.get(iden) orelse return null; return .{ .rest = supz.rest.load(.monotonic), .aliv = !supz.exit.load(.acquire) }; }
pub fn probStat(self: *Sche, iden: []const u8) ?[]const u8 { for (self.arme) |*arme| { if (std.mem.eql(u8, arme.id, iden)) return arme.probeState(); } return null; }
